const inputs=[[0.2, 0.1, 0, -0.4, 1.5, 0.8, 0.4], [0.7, 0.4, 0.2, -0.4, 1.5, 0.8, 0.4], [-0.3, 0, 0.1, -0.4, 1.5, 0.8, 0.4]];
const scores=inputs.map(v=>{
  const [uT,uV,uI,b0,bT,bV,bI]=v;
  return 1/(1+Math.exp(-(b0+bT*uT+bV*uV+bI*uI)));
});
return scores.map((score,index)=>({json:{index,score,alert:score>=0.65}}));
